  "Could not share. Copy the page URL from your browser.": { nb: "Kunne ikke dele. Kopier nettadressen fra nettleseren.", ar: "تعذّرت المشاركة. انسخ رابط الصفحة من المتصفح." },
  "The email provider accepted the invitation. Delivery can take a moment; the secure link expires after 7 days.": { nb: "E-postleverandøren godtok invitasjonen. Det kan ta litt tid før den kommer frem; den sikre lenken utløper etter 7 dager.", ar: "قبل مزوّد البريد الدعوة للإرسال. قد يستغرق وصولها بعض الوقت؛ وينتهي الرابط الآمن بعد 7 أيام." },
  "Could not change role.": { nb: "Kunne ikke endre rolle.", ar: "تعذّر تغيير الدور." },
  "Could not change role. Check your connection and try again.": { nb: "Kunne ikke endre rolle. Kontroller tilkoblingen og prøv igjen.", ar: "تعذّر تغيير الدور. تحقّق من الاتصال وحاول مرة أخرى." },
  "Role updated": { nb: "Rolle oppdatert", ar: "تم تحديث الدور" },
  "Remove this member from the workspace?": { nb: "Fjerne dette medlemmet fra arbeidsområdet?", ar: "هل تريد إزالة هذا العضو من مساحة العمل؟" },
  "Could not remove member.": { nb: "Kunne ikke fjerne medlemmet.", ar: "تعذّرت إزالة العضو." },
  "Could not remove member. Check your connection and try again.": { nb: "Kunne ikke fjerne medlemmet. Kontroller tilkoblingen og prøv igjen.", ar: "تعذّرت إزالة العضو. تحقّق من الاتصال وحاول مرة أخرى." },
  "Revoke this invitation? The link will stop working.": { nb: "Tilbakekalle invitasjonen? Lenken slutter å virke.", ar: "هل تريد إلغاء الدعوة؟ سيتوقف الرابط عن العمل." },
  "Could not revoke invitation.": { nb: "Kunne ikke tilbakekalle invitasjonen.", ar: "تعذّر إلغاء الدعوة." },
  "Could not revoke invitation. Check your connection and try again.": { nb: "Kunne ikke tilbakekalle invitasjonen. Kontroller tilkoblingen og prøv igjen.", ar: "تعذّر إلغاء الدعوة. تحقّق من الاتصال وحاول مرة أخرى." },
  "Revoked": { nb: "Tilbakekalt", ar: "ملغاة" },
  "Add a short reason before rejecting this request.": { nb: "Legg til en kort begrunnelse før du avslår forespørselen.", ar: "أضف سببًا مختصرًا قبل رفض الطلب." },
  "The decision could not be recorded. Refresh and try again.": { nb: "Beslutningen kunne ikke registreres. Oppdater siden og prøv igjen.", ar: "تعذّر تسجيل القرار. حدّث الصفحة وحاول مرة أخرى." },
  "The decision could not be reached. Check your connection and try again.": { nb: "Beslutningen kunne ikke fullføres. Kontroller tilkoblingen og prøv igjen.", ar: "تعذّر إتمام القرار. تحقّق من الاتصال وحاول مرة أخرى." },
  "Reject request": { nb: "Avslå forespørselen", ar: "ارفض الطلب" },
  "Record the reason or any condition for this decision.": { nb: "Registrer begrunnelsen eller eventuelle vilkår for beslutningen.", ar: "سجّل سبب القرار أو أي شروط مرتبطة به." },
