  "This mission is closed. No further work is expected.": { nb: "Oppdraget er lukket. Ingen videre arbeid er forventet.", ar: "أُغلقت المهمة. لا يُتوقع عمل إضافي." },
  "Outcome recorded": { nb: "Resultat registrert", ar: "تم تسجيل النتيجة" },
