  "Add the work this mission needs.": { nb: "Legg til arbeidet oppdraget trenger.", ar: "أضف العمل الذي تحتاجه هذه المهمة." },
  "Ready to check": { nb: "Klar for kontroll", ar: "جاهز للتحقق" },
  "Every action is resolved. Move this mission to checking the evidence.": { nb: "Alle handlinger er avklart. Flytt oppdraget til kontroll av dokumentasjonen.", ar: "تم حسم جميع الإجراءات. انقل المهمة إلى مرحلة التحقق من الأدلة." },
  "Commit the verified outcome": { nb: "Registrer det verifiserte resultatet", ar: "اعتمد النتيجة التي تم التحقق منها" },
  "Passing verification is recorded but no outcome has been committed.": { nb: "Godkjent verifisering er registrert, men resultatet er ikke endelig registrert.", ar: "تم تسجيل اجتياز التحقق، لكن النتيجة لم تُعتمد بعد." },
  "Record verification": { nb: "Registrer verifisering", ar: "سجّل التحقق" },
